"""Tests for the parse stage of the report pipeline."""
from decimal import Decimal
import pytest
from report_pipeline.parse import parse


class TestParseValidInputs:
    def test_single_revenue_row(self):
        rows = parse(["1:REVENUE:1000.00:2024-Q1"])
        assert rows == [{"row_id": 1, "category": "REVENUE", "value": Decimal("1000.00"), "period": "2024-Q1"}]

    def test_single_cost_row(self):
        rows = parse(["2:COST:-200.50:2024-Q1"])
        assert rows == [{"row_id": 2, "category": "COST", "value": Decimal("-200.50"), "period": "2024-Q1"}]

    def test_cost_row_positive_value(self):
        rows = parse(["3:COST:500.00:2024-Q2"])
        assert rows == [{"row_id": 3, "category": "COST", "value": Decimal("500.00"), "period": "2024-Q2"}]

    def test_single_headcount_row(self):
        rows = parse(["4:HEADCOUNT:10:2024-Q1"])
        assert rows == [{"row_id": 4, "category": "HEADCOUNT", "value": Decimal("10"), "period": "2024-Q1"}]

    def test_multiple_rows(self):
        rows = parse([
            "1:REVENUE:5000.00:2024-Q1",
            "2:COST:-1000.00:2024-Q1",
            "3:HEADCOUNT:50:2024-Q1",
        ])
        assert len(rows) == 3
        assert rows[0]["category"] == "REVENUE"
        assert rows[1]["category"] == "COST"
        assert rows[2]["category"] == "HEADCOUNT"

    def test_all_quarters(self):
        inputs = [
            f"{i+1}:REVENUE:100:2024-Q{i+1}" for i in range(4)
        ]
        rows = parse(inputs)
        assert len(rows) == 4
        periods = [r["period"] for r in rows]
        assert periods == ["2024-Q1", "2024-Q2", "2024-Q3", "2024-Q4"]

    def test_multiple_periods(self):
        rows = parse([
            "1:REVENUE:1000:2023-Q4",
            "2:REVENUE:2000:2024-Q1",
        ])
        assert rows[0]["period"] == "2023-Q4"
        assert rows[1]["period"] == "2024-Q1"

    def test_empty_input(self):
        rows = parse([])
        assert rows == []

    def test_integer_value(self):
        rows = parse(["1:REVENUE:1000:2024-Q1"])
        assert rows[0]["value"] == Decimal("1000")

    def test_row_id_is_integer(self):
        rows = parse(["42:REVENUE:100:2024-Q1"])
        assert rows[0]["row_id"] == 42
        assert isinstance(rows[0]["row_id"], int)

    def test_zero_value_revenue(self):
        rows = parse(["1:REVENUE:0.00:2024-Q1"])
        assert rows[0]["value"] == Decimal("0.00")

    def test_zero_value_headcount(self):
        rows = parse(["1:HEADCOUNT:0:2024-Q1"])
        assert rows[0]["value"] == Decimal("0")


class TestParseErrors:
    def _assert_error(self, result, expected_input=None, reason_contains=None):
        assert isinstance(result, dict)
        assert result.get("stage") == "parse"
        assert "input" in result
        assert "reason" in result
        if expected_input is not None:
            assert result["input"] == expected_input
        if reason_contains is not None:
            assert reason_contains.lower() in result["reason"].lower()

    def test_too_few_fields(self):
        result = parse(["1:REVENUE:1000"])
        self._assert_error(result, "1:REVENUE:1000")

    def test_too_many_fields(self):
        result = parse(["1:REVENUE:1000:2024-Q1:extra"])
        self._assert_error(result, "1:REVENUE:1000:2024-Q1:extra")

    def test_invalid_row_id_zero(self):
        result = parse(["0:REVENUE:1000:2024-Q1"])
        self._assert_error(result, "0:REVENUE:1000:2024-Q1")

    def test_invalid_row_id_negative(self):
        result = parse(["-1:REVENUE:1000:2024-Q1"])
        self._assert_error(result, "-1:REVENUE:1000:2024-Q1")

    def test_invalid_row_id_non_integer(self):
        result = parse(["abc:REVENUE:1000:2024-Q1"])
        self._assert_error(result, "abc:REVENUE:1000:2024-Q1")

    def test_invalid_category(self):
        result = parse(["1:PROFIT:1000:2024-Q1"])
        self._assert_error(result, "1:PROFIT:1000:2024-Q1", "category")

    def test_invalid_value_non_numeric(self):
        result = parse(["1:REVENUE:abc:2024-Q1"])
        self._assert_error(result, "1:REVENUE:abc:2024-Q1", "value")

    def test_negative_revenue_is_error(self):
        result = parse(["1:REVENUE:-100:2024-Q1"])
        self._assert_error(result, "1:REVENUE:-100:2024-Q1")

    def test_negative_headcount_is_error(self):
        result = parse(["1:HEADCOUNT:-5:2024-Q1"])
        self._assert_error(result, "1:HEADCOUNT:-5:2024-Q1")

    def test_invalid_period_format(self):
        result = parse(["1:REVENUE:1000:2024-Q5"])
        self._assert_error(result, "1:REVENUE:1000:2024-Q5", "period")

    def test_invalid_period_no_quarter(self):
        result = parse(["1:REVENUE:1000:2024"])
        self._assert_error(result, "1:REVENUE:1000:2024", "period")

    def test_invalid_period_wrong_format(self):
        result = parse(["1:REVENUE:1000:Q1-2024"])
        self._assert_error(result, "1:REVENUE:1000:Q1-2024", "period")

    def test_invalid_period_q0(self):
        result = parse(["1:REVENUE:1000:2024-Q0"])
        self._assert_error(result, "1:REVENUE:1000:2024-Q0", "period")

    def test_duplicate_row_id(self):
        result = parse(["1:REVENUE:1000:2024-Q1", "1:COST:500:2024-Q1"])
        self._assert_error(result)

    def test_returns_first_failing_row(self):
        result = parse([
            "1:REVENUE:1000:2024-Q1",
            "2:INVALID:500:2024-Q1",
            "3:HEADCOUNT:10:2024-Q1",
        ])
        self._assert_error(result, "2:INVALID:500:2024-Q1", "category")

"""Tests for the aggregate stage of the report pipeline."""
from decimal import Decimal
import pytest
from report_pipeline.aggregate import aggregate


def make_row(row_id, category, value, period):
    return {"row_id": row_id, "category": category, "value": Decimal(str(value)), "period": period}


class TestAggregateStructure:
    def test_returns_dict_with_required_keys(self):
        rows = [make_row(1, "REVENUE", "1000", "2024-Q1")]
        result = aggregate(rows)
        assert "cells" in result
        assert "period_totals" in result
        assert "category_totals" in result
        assert "periods" in result
        assert "categories" in result

    def test_periods_ordered_chronologically(self):
        rows = [
            make_row(1, "REVENUE", "1000", "2024-Q2"),
            make_row(2, "REVENUE", "2000", "2023-Q4"),
            make_row(3, "REVENUE", "3000", "2024-Q1"),
        ]
        result = aggregate(rows)
        assert result["periods"] == ["2023-Q4", "2024-Q1", "2024-Q2"]

    def test_categories_in_fixed_order(self):
        rows = [
            make_row(1, "HEADCOUNT", "10", "2024-Q1"),
            make_row(2, "COST", "500", "2024-Q1"),
            make_row(3, "REVENUE", "1000", "2024-Q1"),
        ]
        result = aggregate(rows)
        assert result["categories"] == ["REVENUE", "COST", "HEADCOUNT"]

    def test_categories_only_present_categories(self):
        rows = [make_row(1, "REVENUE", "1000", "2024-Q1")]
        result = aggregate(rows)
        assert result["categories"] == ["REVENUE"]

    def test_categories_two_present(self):
        rows = [
            make_row(1, "REVENUE", "1000", "2024-Q1"),
            make_row(2, "COST", "500", "2024-Q1"),
        ]
        result = aggregate(rows)
        assert result["categories"] == ["REVENUE", "COST"]


class TestAggregateCells:
    def test_single_cell(self):
        rows = [make_row(1, "REVENUE", "1000", "2024-Q1")]
        result = aggregate(rows)
        assert result["cells"][("2024-Q1", "REVENUE")] == Decimal("1000")

    def test_sums_multiple_rows_same_period_category(self):
        rows = [
            make_row(1, "REVENUE", "1000", "2024-Q1"),
            make_row(2, "REVENUE", "500", "2024-Q1"),
        ]
        result = aggregate(rows)
        assert result["cells"][("2024-Q1", "REVENUE")] == Decimal("1500")

    def test_missing_combination_defaults_to_zero(self):
        rows = [make_row(1, "REVENUE", "1000", "2024-Q1")]
        result = aggregate(rows)
        assert result["cells"].get(("2024-Q1", "COST"), Decimal("0")) == Decimal("0")

    def test_negative_cost_value(self):
        rows = [make_row(1, "COST", "-200", "2024-Q1")]
        result = aggregate(rows)
        assert result["cells"][("2024-Q1", "COST")] == Decimal("-200")

    def test_multiple_periods_same_category(self):
        rows = [
            make_row(1, "REVENUE", "1000", "2024-Q1"),
            make_row(2, "REVENUE", "2000", "2024-Q2"),
        ]
        result = aggregate(rows)
        assert result["cells"][("2024-Q1", "REVENUE")] == Decimal("1000")
        assert result["cells"][("2024-Q2", "REVENUE")] == Decimal("2000")


class TestAggregatePeriodTotals:
    def test_single_period_single_category(self):
        rows = [make_row(1, "REVENUE", "1000", "2024-Q1")]
        result = aggregate(rows)
        assert result["period_totals"]["2024-Q1"] == Decimal("1000")

    def test_single_period_multiple_categories(self):
        rows = [
            make_row(1, "REVENUE", "1000", "2024-Q1"),
            make_row(2, "COST", "-200", "2024-Q1"),
            make_row(3, "HEADCOUNT", "10", "2024-Q1"),
        ]
        result = aggregate(rows)
        assert result["period_totals"]["2024-Q1"] == Decimal("810")

    def test_multiple_periods(self):
        rows = [
            make_row(1, "REVENUE", "1000", "2024-Q1"),
            make_row(2, "REVENUE", "2000", "2024-Q2"),
        ]
        result = aggregate(rows)
        assert result["period_totals"]["2024-Q1"] == Decimal("1000")
        assert result["period_totals"]["2024-Q2"] == Decimal("2000")


class TestAggregateCategoryTotals:
    def test_single_category_single_period(self):
        rows = [make_row(1, "REVENUE", "1000", "2024-Q1")]
        result = aggregate(rows)
        assert result["category_totals"]["REVENUE"] == Decimal("1000")

    def test_single_category_multiple_periods(self):
        rows = [
            make_row(1, "REVENUE", "1000", "2024-Q1"),
            make_row(2, "REVENUE", "2000", "2024-Q2"),
        ]
        result = aggregate(rows)
        assert result["category_totals"]["REVENUE"] == Decimal("3000")

    def test_multiple_categories(self):
        rows = [
            make_row(1, "REVENUE", "5000", "2024-Q1"),
            make_row(2, "COST", "-1000", "2024-Q1"),
        ]
        result = aggregate(rows)
        assert result["category_totals"]["REVENUE"] == Decimal("5000")
        assert result["category_totals"]["COST"] == Decimal("-1000")

    def test_headcount_total(self):
        rows = [
            make_row(1, "HEADCOUNT", "10", "2024-Q1"),
            make_row(2, "HEADCOUNT", "5", "2024-Q2"),
        ]
        result = aggregate(rows)
        assert result["category_totals"]["HEADCOUNT"] == Decimal("15")


class TestAggregateEmpty:
    def test_empty_input(self):
        result = aggregate([])
        assert result["periods"] == []
        assert result["categories"] == []
        assert result["cells"] == {}
        assert result["period_totals"] == {}
        assert result["category_totals"] == {}

"""Parse stage: transform raw strings into structured row dicts."""
import re
from decimal import Decimal, InvalidOperation

VALID_CATEGORIES = {"REVENUE", "COST", "HEADCOUNT"}
PERIOD_PATTERN = re.compile(r"^\d{4}-Q[1-4]$")


def _make_error(input_str: str, reason: str) -> dict:
    return {"stage": "parse", "input": input_str, "reason": reason}


def parse(raw_rows: list[str]):
    """
    Parse a list of raw strings into structured row dicts.

    Each string must be in the format: "{ROW_ID}:{CATEGORY}:{VALUE}:{PERIOD}"

    Returns:
        list of dicts with keys: row_id, category, value, period
        OR a structured error dict if any row is invalid.
    """
    results = []
    seen_ids = set()

    for raw in raw_rows:
        parts = raw.split(":")
        if len(parts) != 4:
            return _make_error(raw, f"Expected 4 fields separated by ':', got {len(parts)}")

        row_id_str, category, value_str, period = parts

        # Validate row_id
        try:
            row_id = int(row_id_str)
        except ValueError:
            return _make_error(raw, f"ROW_ID must be a positive integer, got '{row_id_str}'")

        if row_id <= 0:
            return _make_error(raw, f"ROW_ID must be a positive integer, got {row_id}")

        if row_id in seen_ids:
            return _make_error(raw, f"Duplicate ROW_ID: {row_id}")
        seen_ids.add(row_id)

        # Validate category
        if category not in VALID_CATEGORIES:
            return _make_error(raw, f"Invalid category '{category}'; must be one of {sorted(VALID_CATEGORIES)}")

        # Validate value
        try:
            value = Decimal(value_str)
        except InvalidOperation:
            return _make_error(raw, f"VALUE must be a decimal number, got '{value_str}'")

        if category in ("REVENUE", "HEADCOUNT") and value < 0:
            return _make_error(raw, f"Negative VALUE is not allowed for category '{category}'")

        # Validate period
        if not PERIOD_PATTERN.match(period):
            return _make_error(raw, f"PERIOD must be in format YYYY-QN (N=1-4), got '{period}'")

        results.append({
            "row_id": row_id,
            "category": category,
            "value": value,
            "period": period,
        })

    return results

