def _parse_value_from_cell(cell_str: str) -> Decimal | None:
    """
    Parse a formatted cell value back to Decimal.
    Supports: $1,234.56  -$1,234.56  42  $0.00
    """
    cell_str = cell_str.strip()
    if not cell_str:
